import{_ as e,k as t,v as n}from"./app-Xgp6P-Ux.js";import{t as r}from"./plugin-vue_export-helper-BDNMzG2s.js";import"./gzh-BO4QB3XE.js";import"./zsxq-BKcsYlFO.js";var i=JSON.parse(`{"path":"/column/Programmingthinking/31-All-artificial-intelligence-turns-out-to-be-very-weak.html","title":"32-所有的人工智能竟然都很弱？","lang":"zh-CN","frontmatter":{"title":"32-所有的人工智能竟然都很弱？","icon":"read","date":"2025-04-26T14:37:42.000Z","author":"AI悦创","isOriginal":true,"sticky":false,"star":false,"article":true,"timeline":true,"image":false,"navbar":true,"sidebarIcon":true,"comment":true,"lastUpdated":true,"editLink":true,"backToTop":true,"toc":true,"feed":false,"seo":false,"head":[]},"git":{"createdTime":1669634625000,"updatedTime":1745650006000,"contributors":[{"name":"AndersonHJB","username":"AndersonHJB","email":"cleland1432803776@icloud.com","commits":8,"url":"https://github.com/AndersonHJB"},{"name":"AI悦创","username":"","email":"cleland1432803776@icloud.com","commits":1}],"changelog":[{"hash":"c02ee1305e2c7c0fd9014d9f870836445c7dcc95","time":1745650006000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"init"},{"hash":"5e09f72a9f3d0e1c6b3071fd84c3809c76136d7e","time":1745649742000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"init"},{"hash":"a2bcd18dbd6b8b3cefb8b96f0ab4ad5e3ac5f65d","time":1745649547000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add initial draft for \\"All artificial intelligence turns out to be very weak\\" article"},{"hash":"4d098f34b968c7f9162e7d143141d46669c76d6e","time":1745325668000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"Add articles on programming and cooking: \\"Can computer programs really kill people?\\" and \\"清蒸鲈鱼\\""},{"hash":"1c35a6532eb53bd6ed2f2afd6f70564646e80c01","time":1744328990000,"email":"bornforthis@bornforthis.cn","author":"AndersonHJB","message":"去掉head"},{"hash":"cbb3a0f217ea57089ad27386b3127e612324b609","time":1675049774000,"email":"cleland1432803776@icloud.com","author":"AI悦创","message":"update"},{"hash":"76989bb701c8ac79bbc7e2e46050c8b08855befd","time":1670605630000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"86c50aa64ad737c1db38d74dbb5ec22bb6c5bbeb","time":1670575429000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"update"},{"hash":"027da62f7fafa8a29d6f7ba006e9bff7ac22acfe","time":1669634625000,"email":"cleland1432803776@icloud.com","author":"AndersonHJB","message":"first commit"}]},"readingTime":{"minutes":7.89,"words":2367},"filePathRelative":"column/Programmingthinking/31-All-artificial-intelligence-turns-out-to-be-very-weak.md"}`),a={name:`31-All-artificial-intelligence-turns-out-to-be-very-weak.md`};function o(r,i,a,o,s,c){return t(),e(`div`,null,[...i[0]||=[n(`<p>你好，我是悦创。</p><p>你还记得我们前面说过的电影<strong>《机械姬》</strong>吗？里面的机器人<strong>艾娃</strong>杀死了自己的创造者，逃出了实验室。</p><p>其实，这种机器人造反的情节在科幻电影里特别常见，比方在<strong>《复仇者联盟》</strong>里，人工智能<strong>奥创</strong>就想消灭人类。</p><p>那你是不是好奇了，在现实生活中，人工智能已经变得越来越厉害了。将来，它们会不会反抗人类呢？你还别说，科学家们还真思考过这个问题。</p><p><strong>加州大学洛杉矶分校</strong>的科学家把人工智能分成了两类，一类叫<strong>鹦鹉智能</strong>，一类叫<strong>乌鸦智能</strong>。</p><figure><img src="/assets/3a188d28d0d1375d75e525ed570481f8-D0OqZHEA.jpg" alt="鹦鹉" tabindex="0" loading="lazy"><figcaption>鹦鹉</figcaption></figure><p>什么意思呢？我先来给你说说这两种动物。</p><p>人工智能专家认为，鹦鹉虽然也很聪明，还能学咱们说话，但它们并不理解说的话究竟是什么意思，只是单纯地模仿。要是就学了一句话，回答什么都用这句。</p><p>你问它吃饭了么？它说吃了。你问它哥哥去哪了？它也说吃了。这可能就闹笑话啦。</p><p>而乌鸦呢？它们有更强的<strong>思考能力</strong>。</p><p>你可能已经学习过乌鸦喝水的故事了。实际上，乌鸦的智慧可能远远超过你的想象。在<strong>日本</strong>有一种<strong>乌鸦</strong>，甚至能把咱们人类当工具使。</p><figure><img src="/assets/700d056cea136091ec6f6c6f12c83b48-Dpt3tx1P.jpg" alt="乌鸦" tabindex="0" loading="lazy"><figcaption>乌鸦</figcaption></figure><p>这种乌鸦喜欢吃<strong>核桃</strong>。但核桃壳多硬呀，乌鸦自己啄不开。于是，聪明的乌鸦就把核桃扔到马路上，等汽车把核桃压碎了，就飞过去捡核桃仁吃。</p><p>但光是这样还不行，马路上车来车往的，乌鸦一个不小心就会被车撞到，核桃没吃到，可能小命就没了。</p><p>怎么办呢？乌鸦就改进了策略，它们学会了<strong>看红绿灯</strong>。绿灯亮起的时候，它们就把核桃扔到路上，让汽车把核桃压开。等红灯亮起，所有的车都停下来了，乌鸦就飞下去把核桃仁叼起来吃。很有意思吧？</p><p>你看，乌鸦就不是简单地模仿了，它们跟咱们人类思考问题的方式有点像。</p><figure><img src="/assets/4777c3381ace41d608a3e7a3dcaf44bd-blZ-HNHB.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>人工智能专家认为，咱们今天的<strong>人工智能技术</strong>，比如前面课程里说的<strong>Alpha Go</strong>、<strong>推荐算法</strong>、<strong>语音识别系统</strong>，都只能是<strong>鹦鹉智能</strong>。它们只是在模仿人类的思考过程，并不理解自己为什么要这么做，不能自主思考。</p><p>这样的人工智能，它的知识、技能是没办法<strong>迁移</strong>到其他领域上去的，比如Alpha Go就不可能去写诗，语音识别系统也没法给你推荐动画片。这样的人工智能当然也没什么好怕的了，Alpha Go总不能靠下围棋来统治世界吧。所以呀，也有人把这一类人工智能叫<strong>弱人工智能</strong>。</p><p>相比之下，<strong>乌鸦智能</strong>就厉害多了。</p><p>咱们前面课程里介绍过的<strong>机械姬艾娃</strong>，就属于这类人工智能。她有自己的意识，能想办法逃出实验室，而且人类能做到的事她都能做。这一类人工智能也被叫做<strong>强人工智能</strong>，想一想它们确实挺强的。</p><p>那人类会不会造出这样的人工智能呢？科学家做了很多很多尝试，但还没有成功。不过，有一种研究方法看起来比较有戏，而且啊，也特别有意思，我给你们讲一讲。</p><figure><img src="https://coolcdn.igetcool.com/p/2021/3/6e482762096f8f7a68f3c32a0179e4fd.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>这种方法是通过<strong>模仿生物进化</strong>，让人工智能自己总结经验，学会思考。其中比较成功的一个项目，是让人工智能玩捉迷藏<strong>大战</strong>。</p><p>怎么玩呢？规则很简单，科学家在计算机里设置了一片场地，里面有红色小人和蓝色小人。</p><p>在规定的时间里，只要红色小人抓住了蓝色小人，那红色小人就得1分，蓝色小人扣1分。如果红色小人没抓到蓝色小人呢，那蓝色小人就得1分，红色小人扣1分。</p><p>当然了，房间里还有一些箱子、木板这样的道具，红蓝小人都可以用。每完成一局比赛，红蓝小人都会<strong>总结经验</strong>，争取在下一局里变得更厉害，就像是生物进化一样。</p><p>规则设计好了之后，科学家就让计算机自己玩捉迷藏游戏了。</p><figure><img src="/assets/e2111ebbce50f6aab7b244d677591e51-DXvDbnNg.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>一开始，小红人和小蓝人的智慧还在意料之中，无非就是躲在房间的角落里。后来经过<strong>几百万</strong>次训练，小蓝人学会了用方块把门堵上，不让小红人进来。小红人呢，也渐渐学会了用木板搭一个梯子，闯进房间里。</p><p>那如果你是小蓝人，你会怎么办呢？对了，在开局的时候先把木板搬进房间里，再用方块把门都堵上，这样小红人就彻底没办法了。</p><p>不过，科学家又改变了场地环境，在场地里多放了一些道具。经过<strong>几亿</strong>次的训练，小红人和小蓝人的技能又在不断提高，比如小蓝人学会了用木板和箱子就地搭建一个小房子。</p><p>你看，本来是毫无智慧的小红人、小蓝人，在上亿次进化之后，居然也获得了这么高级的能力。</p><p>那我们如果虚拟出来一个更真实、更复杂的环境，小红人、小蓝人能不能学会说话、写作业、打游戏，以及人类能干的一切事物呢？</p><p>换句话说，我们能不能通过计算机<strong>模拟进化</strong>，造出来<strong>强人工智能</strong>呢？听起来挺有希望的，但实际上要实现这一点还太遥远了。</p><p>这主要是因为，人类对自己的<strong>大脑运作原理</strong>都了解得不够透彻。在这个基础上，想要让计算机学会人类的思考方式，想让它们拥有人类的智能，几乎是不可能的。</p><p>就拿刚刚说过的进化路线来说吧，很多人做类似的实验就完全失败了。</p><figure><img src="/assets/855cb9aed03149c5c12eef72ecddd478-D9WXaa4a.jpg" alt="狼" tabindex="0" loading="lazy"><figcaption>狼</figcaption></figure><p>我也给你举个好玩的例子吧，有一位研究者做了一个<strong>狼捉羊</strong>的模拟实验。本质上跟前边说的捉迷藏游戏差不了多少，只是把小红和小蓝换成了狼和羊。不过，他在制定游戏规则的时候，为了督促狼更快地捕捉到羊，每过一秒种就给狼扣掉0.01分，而狼捕捉到羊可以得到10分。</p><p>结果，在进行了<strong>20万</strong>次实验之后，出现了非常奇怪的事：狼的心理崩溃了！每次游戏一开始，狼就对着石头撞了起来，直到把自己活活撞死。</p><p>诶，前边小红人小蓝人都变得那么厉害，怎么轮到狼就只学会自杀了呢？原来，在这个游戏里，<strong>狼实在是太难捉到羊了</strong>，与其等下去每秒钟都要扣分，那还不如一开局就死了算了，扣的分还少一点。</p><p>你看，在相似的实验中，人工智能的行为完全不一样，有的学会了聪明的策略，有的却崩溃到自杀。要想通过这种方法，获得非常高级的人工智能，真的是很难的一条路呀。</p><figure><img src="/assets/be2b5f4b8e4306c742ec6dabc30ef07e-BIgA6KN7.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure><p>或许，我们需要在<strong>生物</strong>、<strong>数学</strong>、<strong>物理</strong>、<strong>化学</strong>等等，学科上都作出更大的突破，才有可能造出强人工智能，这件事，很可能将来就要靠你完成了。所以现在，你压根就不用担心人工智能会站起来反抗人类。</p><p>那到这里，我们的编程思维课就结束了。希望你能够把学到的编程思维运用到生活中，解决生活中的一个个难题，我们后会有期。</p><details class="hint-container details"><summary>公众号：AI悦创【二维码】</summary><figure><img src="/gzh.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure></details><div class="hint-container info"><p class="hint-container-title">AI悦创·编程一对一</p><p>AI悦创·推出辅导班啦，包括「Python 语言辅导班、C++ 辅导班、java 辅导班、算法/数据结构辅导班、少儿编程、pygame 游戏开发、Web、Linux」，招收学员面向国内外，国外占 80%。全部都是一对一教学：一对一辅导 + 一对一答疑 + 布置作业 + 项目实践等。当然，还有线下线上摄影课程、Photoshop、Premiere 一对一教学、QQ、微信在线，随时响应！微信：Jiabcdefh</p><p>C++ 信息奥赛题解，长期更新！长期招收一对一中小学信息奥赛集训，莆田、厦门地区有机会线下上门，其他地区线上。微信：Jiabcdefh</p><p>方法一：<a href="http://wpa.qq.com/msgrd?v=3&amp;uin=1432803776&amp;site=qq&amp;menu=yes" target="_blank" rel="noopener noreferrer">QQ</a></p><p>方法二：微信：Jiabcdefh</p></div><figure><img src="/zsxq.jpg" alt="" tabindex="0" loading="lazy"><figcaption></figcaption></figure>`,48)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};